from pathlib import Path
from html import escape
ROOT=Path(__file__).parent
spec=ROOT.parent/'05_TECHNICAL_ARCHITECTURE.md'
# Faithful excerpt of an actual supplied document, not invented engineering evidence.
diagram=spec.read_text().split('```text\n',1)[1].split('```',1)[0]
lines=diagram.splitlines()[:15]
svg='<svg xmlns="http://www.w3.org/2000/svg" width="900" height="580" viewBox="0 0 900 580"><rect width="900" height="580" fill="#e9e7df"/><text x="40" y="45" fill="#545950" font-family="Arial,sans-serif" font-size="16" letter-spacing="2">SOURCE EXCERPT / ARCHITECTURE PLAN</text>'
for i,line in enumerate(lines):
    svg+=f'<text x="40" y="{94+i*27}" xml:space="preserve" fill="#252c29" font-family="monospace" font-size="19">{escape(line)}</text>'
svg+='<path d="M40 520H860" stroke="#969b91"/><text x="40" y="550" fill="#545950" font-family="Arial,sans-serif" font-size="16">Planning material. No implementation or validation is claimed.</text></svg>'
(ROOT/'assets/architecture-excerpt.svg').write_text(svg)
nav='<a href="#work">Work</a><a href="#open-source">Open source</a><a href="#notes">Notes</a><a href="#about">About</a>'
figure='''<figure class="evidence-figure"><a href="assets/architecture-excerpt.svg" aria-label="Enlarge supplied architecture-plan excerpt"><img src="assets/architecture-excerpt.svg" width="900" height="580" alt="Excerpt from the supplied architecture plan showing visitor browser, static files and an Astro build. This is planning material, not an implemented system."></a><figcaption><span>FIG. 01</span> Supplied architecture plan · <strong>not implemented work</strong><a href="assets/architecture-excerpt.svg">Enlarge figure ↗</a></figcaption></figure>'''
intro='''<div class="intro"><p class="eyebrow">Personal engineering journal</p><h1>At the meeting point<br class="desktop-break"> of software<br class="desktop-break"> and hardware.</h1><p class="lead">I’m Sashi, a second-year Electronics and Communication Engineering student.</p><p class="intro-copy">Exploring embedded systems, software engineering, digital hardware, AI and robotics.</p><div class="intro-actions"><a class="action" href="#work">Explore the journal <span aria-hidden="true">↘</span></a><a href="#about">About me <span aria-hidden="true">→</span></a></div></div>'''
figure=figure.replace('</figure>', '<details class="figure-transcript"><summary>Read figure text</summary><pre>'+escape('\n'.join(lines))+'</pre></details></figure>')
caseintro='''<div class="case-copy"><p class="fixture">Layout fixture 01 · not portfolio work</p><h3>A technical question.<br> A traceable investigation.</h3><p>This specimen shows where a real project’s question, constraints and scope would appear. No project, result or contribution is claimed.</p><dl class="record"><div><dt>Role</dt><dd>Awaiting verified project content</dd></div><div><dt>Evidence</dt><dd>Planning excerpt only</dd></div><div><dt>Validation</dt><dd>No test result supplied</dd></div></dl><a class="text-link" href="#specimen-note">Read the specimen annotation <span aria-hidden="true">→</span></a></div>'''
textcase='''<article class="text-case"><div class="case-index" aria-hidden="true">02</div><div><p class="fixture">Layout fixture 02 · text-only presentation</p><h3>When the explanation is the artifact.</h3><p>A considered account of the problem, method and limitations can stand on its own. This is layout copy; it does not describe completed work.</p><p class="text-meta">Image optional <span aria-hidden="true">/</span> Evidence required before publication</p></div></article>'''
focus='''<section class="focus" aria-labelledby="focus-title"><h2 id="focus-title">Areas of exploration</h2><div><span class="micro">Engineering</span><p>Software, embedded systems<br> and digital hardware.</p></div><div><span class="micro">Open source</span><p>Learning and contribution records,<br> when ready to share.</p></div></section>'''
